fn splitlines(a: Vec<String>, keepends: bool) -> Vec<Vec<String>> {
    a.into_iter()
     .map(|s| {
         if keepends {
             // split_inclusive keeps the '\n' at the end of each line
             s.split_inclusive('\n')
              .map(|piece| piece.to_string())
              .collect()
         } else {
             // split drops the '\n' separators
             s.split('\n')
              .map(|piece| piece.to_string())
              .collect()
         }
     })
     .collect()
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_keepends_false() {
        let input = vec![
            "hello\nworld".to_string(),
            "foo".to_string(),
            "".to_string(),
            "a\nb\n".to_string(),
        ];
        let output = splitlines(input, false);
        assert_eq!(output.len(), 4);
        assert_eq!(output[0], vec!["hello".to_string(), "world".to_string()]);
        assert_eq!(output[1], vec!["foo".to_string()]);
        assert_eq!(output[2], vec!["".to_string()]);       // empty string → one empty element
        assert_eq!(output[3], vec!["a".to_string(), "b".to_string(), "".to_string()]);
    }

    #[test]
    fn test_keepends_true() {
        let input = vec![
            "hello\nworld".to_string(),
            "foo".to_string(),
            "".to_string(),
            "a\nb\n".to_string(),
        ];
        let output = splitlines(input, true);
        assert_eq!(output.len(), 4);
        assert_eq!(output[0], vec!["hello\n".to_string(), "world".to_string()]);
        assert_eq!(output[1], vec!["foo".to_string()]);
        assert_eq!(output[2], vec!["".to_string()]);
        assert_eq!(output[3], vec!["a\n".to_string(), "b\n".to_string()]);
    }
}